import{_ as i,C as o,o as s,c as r,a2 as a,E as t}from"./chunks/framework.CBxkvBm_.js";const y=JSON.parse('{"title":"Linear Memory DAE Arena & Lowering","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/dae-arena.md","filePath":"architecture/dae-arena.md"}'),l={name:"architecture/dae-arena.md"};function c(d,e,p,m,u,h){const n=o("MermaidBlock");return s(),r("div",null,[e[0]||(e[0]=a(`<h1 id="linear-memory-dae-arena-lowering" tabindex="-1">Linear Memory DAE Arena &amp; Lowering <a class="header-anchor" href="#linear-memory-dae-arena-lowering" aria-label="Permalink to &quot;Linear Memory DAE Arena &amp; Lowering&quot;">​</a></h1><p>The Differential Algebraic Equations (DAE) representation in ModelScript is implemented via <code>DAEBuilder</code> in <code>@modelscript/runtime</code> (<code>packages/runtime/src/dae/wasm_dae.ts</code>).</p><p>Unlike traditional compilers that construct linked expression trees using heap-allocated objects, <code>DAEBuilder</code> operates strictly on <strong>flat, contiguous typed arrays</strong> (Struct-of-Arrays) in WebAssembly linear memory.</p><hr><h2 id="arena-struct-of-arrays-soa-layout" tabindex="-1">Arena Struct-of-Arrays (SoA) Layout <a class="header-anchor" href="#arena-struct-of-arrays-soa-layout" aria-label="Permalink to &quot;Arena Struct-of-Arrays (SoA) Layout&quot;">​</a></h2><p>The arena maintains three primary contiguous arrays:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                      DAEBuilder Linear Memory                     │</span></span>
<span class="line"><span>├─────────────────┬──────────────────┬──────────────────────────────┤</span></span>
<span class="line"><span>│ Buffer          │ Element Size     │ Contents                     │</span></span>
<span class="line"><span>├─────────────────┼──────────────────┼──────────────────────────────┤</span></span>
<span class="line"><span>│ varData         │ 32 bytes         │ Name, type, variability,     │</span></span>
<span class="line"><span>│                 │                  │ causality, start value, flags│</span></span>
<span class="line"><span>├─────────────────┼──────────────────┼──────────────────────────────┤</span></span>
<span class="line"><span>│ exprData        │ 16 bytes         │ OpKind, data1, leftExprId,   │</span></span>
<span class="line"><span>│                 │                  │ rightExprId                  │</span></span>
<span class="line"><span>├─────────────────┼──────────────────┼──────────────────────────────┤</span></span>
<span class="line"><span>│ eqData          │ 24 bytes         │ EqKind, lhsExprId,           │</span></span>
<span class="line"><span>│                 │                  │ rhsExprId, flags             │</span></span>
<span class="line"><span>└─────────────────┴──────────────────┴──────────────────────────────┘</span></span></code></pre></div><p>Every variable, expression, and equation is assigned a persistent 32-bit integer handle:</p><ul><li><code>VarId</code>: Handle to a variable in <code>varData</code></li><li><code>ExprId</code>: Handle to an expression node in <code>exprData</code></li><li><code>EqId</code>: Handle to an equation in <code>eqData</code></li></ul><hr><h2 id="lowering-pipeline" tabindex="-1">Lowering Pipeline <a class="header-anchor" href="#lowering-pipeline" aria-label="Permalink to &quot;Lowering Pipeline&quot;">​</a></h2><p>Flattening a high-level Modelica model into linear DAE form proceeds in two coordinated layers:</p><h3 id="layer-1-components-hierarchy" tabindex="-1">Layer 1: Components &amp; Hierarchy <a class="header-anchor" href="#layer-1-components-hierarchy" aria-label="Permalink to &quot;Layer 1: Components &amp; Hierarchy&quot;">​</a></h3><p>Reads Salsa queries (<code>instantiate</code>, <code>classInstance</code>, <code>variability</code>) to allocate variables and parameters in <code>DAEBuilder</code>:</p><ul><li>Scalar variables (<code>Real</code>, <code>Integer</code>, <code>Boolean</code>, <code>String</code>)</li><li>Array dimensions and indices</li><li>Start values, nominals, and min/max boundaries</li></ul><h3 id="layer-2-equations-statements" tabindex="-1">Layer 2: Equations &amp; Statements <a class="header-anchor" href="#layer-2-equations-statements" aria-label="Permalink to &quot;Layer 2: Equations &amp; Statements&quot;">​</a></h3><p>Walks the linear CST of the class body (<code>db.cstNode(classId)</code>):</p><ul><li>Lowers binary, unary, and call expressions directly into <code>ExprId</code> nodes in linear memory.</li><li>Emits equality equations (<code>lhs = rhs</code>), initial equations, and algorithm statements.</li></ul><hr><h2 id="expression-lowering-rules" tabindex="-1">Expression Lowering Rules <a class="header-anchor" href="#expression-lowering-rules" aria-label="Permalink to &quot;Expression Lowering Rules&quot;">​</a></h2><p>To match OpenModelica&#39;s canonical output, the flattener applies specific normalization rules:</p><ol><li><strong>Real Coercion in Binary Operations</strong>: If one operand of an arithmetic operator is <code>Real</code> and the other is <code>Integer</code>, the integer operand is automatically cast to Real using <code>castToRealExpr()</code>.</li><li><strong>Negation Distribution</strong>: Expressions of the form <code>-(a * b)</code> are rewritten canonically to <code>(-a) * b</code>.</li><li><strong>Binding Literal Kind Matching</strong>: When a binding expression is lowered, <code>addIntLiteral()</code> is used for <code>VarType.Integer</code> and <code>addRealLiteral()</code> for <code>VarType.Real</code> (e.g. <code>parameter Real R = 100</code> becomes <code>100.0</code>).</li></ol><hr><h2 id="optimization-transformation-passes" tabindex="-1">Optimization &amp; Transformation Passes <a class="header-anchor" href="#optimization-transformation-passes" aria-label="Permalink to &quot;Optimization &amp; Transformation Passes&quot;">​</a></h2><p>Once lowered to the arena, equations pass through four high-performance transformations:</p>`,25)),t(n,{code:"flowchart%20LR%0A%20%20%20%20LOWER%5B%22DAE%20Lowering%22%5D%20--%3E%20FOLD%5B%221.%20Constant%20Folding%3Cbr%2F%3E(foldArenaConstants)%22%5D%0A%20%20%20%20FOLD%20--%3E%20ALIAS%5B%222.%20Alias%20Elimination%3Cbr%2F%3E(eliminateArenaAliases)%22%5D%0A%20%20%20%20ALIAS%20--%3E%20PANT%5B%223.%20Pantelides%20Algorithm%3Cbr%2F%3E(Index%20Reduction)%22%5D%0A%20%20%20%20PANT%20--%3E%20BLT%5B%224.%20Tarjan%20BLT%3Cbr%2F%3E(Block%20Lower%20Triangular%20Partition)%22%5D%0A%20%20%20%20BLT%20--%3E%20SOLVE%5B%22Numerical%20Solvers%22%5D%0A"}),e[1]||(e[1]=a("<ol><li><strong>Constant Folding (<code>foldArenaConstants</code>)</strong>: Recursively simplifies compile-time constant arithmetic expressions directly in the arena.</li><li><strong>Alias Elimination (<code>eliminateArenaAliases</code>)</strong>: Detects trivial equality equations ($x = y$) generated by connectors and replaces all references with a single canonical variable handle.</li><li><strong>Pantelides Index Reduction</strong>: Differentiates high-index algebraic constraints to reduce the DAE index to 1 or 0 for stable numerical integration.</li><li><strong>Tarjan BLT Partitioning</strong>: Constructs the bipartite incidence graph between variables and equations, computes maximum matching, and finds Strongly Connected Components (SCC) using Tarjan&#39;s algorithm.</li></ol>",1))])}const f=i(l,[["render",c]]);export{y as __pageData,f as default};
